before:
Complete local Go example; the app itself does not execute it:
```go
package main
import ("fmt")
func guarded() {
 defer func() {
  if recover() != nil { fmt.Println("recovered") }
 }()
 panic("broken")
}
func main() {
 guarded()
 fmt.Println("after")
}
```

